var frontierSnapshot = {"generatedAt":"2026-08-24T08:04:02.825Z","cadence":"Every Monday at 07:17 UTC","windowDays":45,"method":"Automated topic matching followed by newest-first ordering. This is a discovery feed, not an impact or efficacy ranking.","sources":[{"id":"europe-pmc","name":"Europe PMC","kind":"paper","url":"https://europepmc.org/RestfulWebService","note":"Newest peer-reviewed and indexed literature matching the atlas topic vocabulary."},{"id":"preprints","name":"Europe PMC preprint index","kind":"preprint","url":"https://europepmc.org/RestfulWebService","note":"Recent preprints indexed from source servers; each item links to its original record and is marked as not yet peer reviewed."},{"id":"clinicaltrials","name":"ClinicalTrials.gov","kind":"trial","url":"https://clinicaltrials.gov/data-api/api","note":"Recently updated registrations, not evidence that a treatment is effective."},{"id":"nibib","name":"NIH NIBIB News","kind":"news","url":"https://www.nibib.nih.gov/rss","note":"Current official biomedical-engineering news feed; item dates are shown as the weekly observation date when the feed omits them."}],"errors":[],"items":[{"id":"preprint-10.64898/2026.08.20.745566","kind":"preprint","title":"GABAergic and glutamatergic synaptic networks and mitochondrial morphology in the thalamic ventral motor and centromedian nuclei of Rhesus Monkey: A comparative 3D Electron Microscopic Analysis between Control and Parkinsonian State","date":"2026-08-23","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.08.20.745566","summary":"The ventral motor and the centromedian (CM) nuclei receive prominent GABAergic inputs from the basal ganglia, massive glutamatergic projections from motor cortices and significant GABAergic afferents from the reticular thalamic nucleus. There is strong evidence that disrupted processing of information through these connections may contribute to the pathophysiology of the basal ganglia-thalamocortical loop in Parkinson's disease (PD). To further assess potential ultrastructural changes in synaptic connectivity and mitochondrial integrity that may contribute to these network dysfunctions, we used a 3D electron mic…","authors":"Masilamoni GJ, Villalba RM, Pare J, Smith Y.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"paper-10.1186/s13244-026-02365-7","kind":"paper","title":"Super-resolution MRI and 2.5D deep learning for intratumoral-peritumoral radiomics in preoperative prediction of rectal cancer perineural invasion.","date":"2026-08-22","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1186/s13244-026-02365-7","summary":"Objectives Preoperative prediction of perineural invasion (PNI) in rectal cancer (RC) is challenging due to limited MRI resolution and the neglect of extramural microenvironmental features. We developed a noninvasive framework integrating super-resolution MRI, 2.5D deep learning (DL), and intratumoral-peritumoral radiomics for preoperative PNI prediction. Materials and methods A dual-center cohort of 312 RC patients with pathologically confirmed PNI status was analyzed. Preoperative MRI underwent 4× super-resolution reconstruction using a generative adversarial network (GAN) to enhance tissue definition. Radiomi…","authors":"Wang Y, Dong D, Shi S, Wu Y, Singh A, Xie J, Chen Q, Zhu J, Li X.","venue":"Insights into imaging","status":"Peer-reviewed / indexed","topics":["record"]},{"id":"paper-10.1016/j.ctarc.2026.101384","kind":"paper","title":"The Brain-tumor axis: Tumor pathogenesis and therapeutic strategies from a cancer neuroscience perspective.","date":"2026-08-22","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.ctarc.2026.101384","summary":"Cancer research has undergone a fundamental paradigm shift, moving beyond a tumor-cell-centric framework toward a systems-level understanding in which the nervous system occupies a central regulatory role. The brain and its peripheral extensions engage in sophisticated, bidirectional crosstalk with tumors across multiple biological scales. This complex relationship, now termed the brain-tumor axis, operates through mechanisms spanning systemic neuroendocrine regulation, local neural-tumor interactions, and the distinctive biology of the central nervous system as both a primary and metastatic tumor site. At the s…","authors":"Liu Y, Guo C, Wang X, Huang K, Huang S, Cao J, Deng M, Guan T, Zhang Y, Tian S, Zheng Z.","venue":"Cancer treatment and research communications","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-10.1007/s10143-026-04456-x","kind":"paper","title":"Brain-spine interface: an exploration of a potential future treatment for spinal cord injury.","date":"2026-08-22","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1007/s10143-026-04456-x","summary":"Spinal cord injuries (SCIs) profoundly impact millions globally, leading to loss of motor and sensory functions below the injury site. Brain-spine interfaces (BSIs) represent an early-stage neuroprosthetic strategy that attempts to restore functional communication between cortical motor-intention signals and spinal sensorimotor circuits below the level of injury. Although early preclinical and highly selected clinical studies have shown encouraging motor outcomes, the evidence remains preliminary, and routine clinical use is limited by questions regarding safety, durability, patient selection, accessibility, and…","authors":"Sivan V, Alam Z, Polavarapu H, Manivel S, Kumar RP, O'Malley GR, Ruzicka F, Patel NV.","venue":"Neurosurgical review","status":"Peer-reviewed / indexed","topics":["stimulate","restore"]},{"id":"paper-10.1002/epi.70445","kind":"paper","title":"Programming of deep brain stimulation of the centromedian nucleus of the thalamus for drug-resistant epilepsy: A meta-analysis and proposed programming framework.","date":"2026-08-22","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1002/epi.70445","summary":"Objective Although the centromedian nucleus of the thalamus (CM) is an increasingly considered deep brain stimulation (DBS) target for drug-resistant epilepsy (DRE), there is significant variability in programming practices, which may contribute to heterogenous outcomes. We systematically described stimulation parameters for CM-DBS and their association with seizure outcomes to inform a standardized, evidence-informed programming framework. Methods We performed a Preferred Reporting Items for Systematic reviews and Meta-Analysis (PRISMA)-guided systematic review and meta-analysis of published studies pertaining…","authors":"AlQahtani MA, Stern-Zimmer M, Jain P, Sharma S, Fasano A, Rotenberg A, Ibrahim GM, Gorodetsky C.","venue":"Epilepsia","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-10.1038/s41386-026-02531-x","kind":"paper","title":"Activation of mu-opioid receptors slows pacemaking in hypothalamic A11 dopamine neurons.","date":"2026-08-21","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1038/s41386-026-02531-x","summary":"Hypothalamic A11 dopamine neurons provide the only known source of spinal dopamine and critically modulate pain and motor systems. Yet, the electrophysiological properties of A11 neurons were unknown. Here, we characterized A11 dopamine neurons in mice using brain slice immunohistochemistry, and fluorescence-guided whole-cell patch-clamp and cell-attached electrophysiology. A11 dopamine neurons contained the enzymes necessary to synthesize dopamine, projected to the spinal cord, and were small, morphologically simple, and high resistance. Additionally, they received excitatory glutamatergic and inhibitory GABAer…","authors":"Smith AF, Rust HN, Sluka KA, Gantz SC.","venue":"Neuropsychopharmacology : official publication of the American College of Neuropsychopharmacology","status":"Peer-reviewed / indexed","topics":["record","restore"]},{"id":"paper-10.1016/j.critrevonc.2026.105556","kind":"paper","title":"CAR-T Cell Therapy for Glioblastoma: Obstacles and Advances.","date":"2026-08-21","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.critrevonc.2026.105556","summary":"Glioblastoma (GBM) is the most aggressive primary malignancy of the central nervous system. Chimeric antigen receptor T (CAR-T) cell therapy has shown promising therapeutic potential against GBM, yet its efficacy remains constrained by multiple barriers, including physical barriers imposed by the blood-brain barrier and extracellular matrix, the immunosuppressive tumor microenvironment, spatiotemporal antigen heterogeneity, and safety concerns. In this review, we summarize the major obstacles limiting CAR-T therapy in GBM and discuss emerging strategies to overcome these challenges. Next-generation engineered CA…","authors":"Chen L, Zou Z.","venue":"Critical reviews in oncology/hematology","status":"Peer-reviewed / indexed","topics":["record","stimulate"]},{"id":"paper-10.1016/j.xcrm.2026.103001","kind":"paper","title":"Cortical-to-pallidal beta cascade underlies network pathophysiology in Parkinson's disease.","date":"2026-08-21","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1016/j.xcrm.2026.103001","summary":"Parkinson's disease (PD) motor symptoms are linked to excessive beta band (13-35 Hz) oscillations and basal ganglia-cortical (BGC) synchrony, yet their dynamic inter-relation remains unclear. Based on computational modeling, we hypothesize that transient high-beta (20-35 Hz) BGC coupling induces subcortical low-beta (13-20 Hz) amplification. We recorded intraoperative neural signals from the globus pallidus internus and externus (GPi and GPe, respectively) and motor cortex (M1) in 23 PD patients during deep brain stimulation implantation. High-beta bursts in M1 and GPe were classified as either temporally synchr…","authors":"Choi JW, Alijanpourotaghsara A, Mirpour K, Chilukuri S, Pouratian N.","venue":"Cell reports. Medicine","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-10.1371/journal.pone.0354976","kind":"paper","title":"Improved motor imagery BCI performance via task-unaware compression in the BELT Bayesian Edge-Cloud architecture.","date":"2026-08-21","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1371/journal.pone.0354976","summary":"Brain-computer interface (BCI) systems have advanced with deep learning, but they are still limited by designs tied to specific applications, poor scalability, weak portability, the need for user-specific adaptation, and privacy concerns. We present BELT, a modular Bayesian Edge-Cloud architecture based on three principles: (i) Bayesian priors and posteriors to balance generalization and subject-specific learning, (ii) lightweight classifiers suitable for embedded devices, and (iii) task-aware compression to reduce bandwidth and improve privacy in edge-cloud communication. To show feasibility, we implement BELT-…","authors":"Danayi A, Soltanian-Zadeh H.","venue":"PloS one","status":"Peer-reviewed / indexed","topics":["record","restore"]},{"id":"paper-10.1007/s10827-026-00954-5","kind":"paper","title":"Network state transitions under deep brain stimulation: A Wilson-Cowan model of Parkinson's Disease.","date":"2026-08-21","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1007/s10827-026-00954-5","summary":"Parkinson's disease is characterized by pathological beta-band oscillations ([Formula: see text]) arising from dopamine-depletion-induced instability in the basal ganglia-thalamocortical network. Although deep brain stimulation of the subthalamic nucleus is the most effective therapy for advanced Parkinson's disease, the mechanistic relationship between stimulation amplitude and network-state transitions remains poorly delineated, limiting the rational design of adaptive closed-loop protocols. We addressed this gap using a seven-population Wilson-Cowan mean-field model in which the Parkinsonian state was induced…","authors":"Singh AR, Singh P.","venue":"Journal of computational neuroscience","status":"Peer-reviewed / indexed","topics":["stimulate"]},{"id":"paper-10.1002/14651858.cd015065.pub2","kind":"paper","title":"Brain-computer interface training for motor recovery after stroke.","date":"2026-08-21","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1002/14651858.cd015065.pub2","summary":"Rationale Stroke is one of the leading causes of death and disability worldwide. Motor dysfunction is a highly prevalent and disabling consequence of stroke. Brain-computer interface (BCI) training has emerged as a promising neurorehabilitative strategy that utilises closed-loop feedback to promote targeted neural plasticity and motor recovery. However, current clinical evidence remains fragmented. Objectives To assess the effects of brain-computer interface training for motor recovery in people after stroke. Search methods We searched the Cochrane Stroke Group's Specialised Register, CENTRAL, MEDLINE, Embase, 1…","authors":"Qin Y, Li M, Li Y, Ma M, Xu J, Lu Y, Shi X, Cui G, Zhao H, Yang K.","venue":"The Cochrane database of systematic reviews","status":"Peer-reviewed / indexed","topics":["record","stimulate","restore","personal"]},{"id":"paper-10.1097/tp.0000000000005879","kind":"paper","title":"Neurocognitive Recovery After Liver Transplantation Is Driven by Metabolite-mediated Reactivation of Cortical Networks.","date":"2026-08-21","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1097/tp.0000000000005879","summary":"Background Liver transplantation (LT) is a life-saving therapy for end-stage liver disease, but postoperative neurocognitive recovery and mechanisms remain unclear. Although liver-brain crosstalk is known, whether LT restores neurological dysfunction is uncertain. Methods Twenty-one patients undergoing LT were prospectively evaluated within 1-3 d before transplantation and 21 d postoperatively. Cognitive function was assessed using the Montreal Cognitive Assessment and the Psychometric Hepatic Encephalopathy Score, and resting-state electroencephalography (EEG) was analyzed for power spectral density, functional…","authors":"Wang T, Nashan B, Wang J, Xu F, Zhang Q, Yang S, Du M, Wang D, Zhao X, Wang Q, Zhang S, Liu J, Liu L, Zhou M.","venue":"Transplantation","status":"Peer-reviewed / indexed","topics":["record"]},{"id":"preprint-10.64898/2026.08.17.745355","kind":"preprint","title":"Arm locomotor behaviour affects motor unit discharge characteristics in the stationary leg","date":"2026-08-21","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.08.17.745355","summary":"Persistent inward currents (PICs), which are facilitated by monoaminergic inputs such as serotonin (5-HT), amplify synaptic drive and strongly influence motoneuron excitability. Although rhythmic locomotor activity increases serotonergic drive in animal models, its effects on intrinsic motoneuron properties in humans remain unclear. We examined whether rhythmic arm cycling alters motoneuron excitability of the non-exercising tibialis anterior during submaximal contractions. Twelve healthy adults (8 males, 4 females) performed triangular isometric dorsiflexion contractions at 25% and 50% MVC under four conditions…","authors":"Nazaroff BM, Mitchell ER, Pearcey G.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.08.18.26360692","kind":"preprint","title":"Left-sided Inhibition Deficit and right-sided Hyperexcitability in Treatment Resistant Bipolar Depression: A TMS-EEG study","date":"2026-08-21","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.08.18.26360692","summary":"Objective: Disruption of the excitation/inhibition balance may contribute to the pathophysiology of bipolar disorder, with post-mortem studies reporting abnormalities in GABA-receptors, interneurons and inhibitory signaling in prefrontal areas. Transcranial magnetic stimulation with electroencephalography (TMS-EEG) enables in vivo assessment of cortical excitability/inhibition. This study examined short-latency intracortical inhibition (SICI) after left- and right-dorsolateral prefrontal cortex (DLPFC) stimulation in bipolar depression (BDep, n=10) and healthy controls (HC, n=22). Methods: SICI (paired-pulse TMS…","authors":"Oostra E, Schipper WL, Tans EB, Regeer EJ, van der Werf YD, van Eijndhoven PF, van den Heuvel OA, van Exel E, d'Angremont E.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","stimulate"]},{"id":"preprint-10.64898/2026.08.17.26360495","kind":"preprint","title":"Music reshapes basal ganglia neural state dynamics toward a medication-like regime in Parkinsons disease","date":"2026-08-21","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.08.17.26360495","summary":"Parkinson disease (PD) is characterized by excessive neural synchronization in the 13 to 30 Hz beta band within basal ganglia circuits. Conventional therapies, including dopaminergic medication and deep brain stimulation (DBS), reduce beta synchrony while enhancing lower-frequency theta activity. As an adjunct to these treatments, music and auditory rhythms improve motor function in PD, but the neural mechanisms remain unclear. Here, we recorded local field potentials in the subthalamic nucleus (STN) of patients with PD in the medication off state to test how structured musical elements shape subcortical synchro…","authors":"Nair SS, Filyushkina V, Chemali K, Guha A, Gamaleya A, Tomskiy A, Sedov A, Shaikh AG.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"trial-nct07780461","kind":"trial","title":"Characterization and Validation of the Short Physical Performance Battery in Individuals Diagnosed With Parkinson's Disease","date":"2026-08-21","observedAt":"2026-08-24","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07780461","summary":"Parkinson's disease (PD) is a progressive neurodegenerative disorder associated with motor and non-motor impairments that affect physical function, mobility, balance, and quality of life. Although Galicia is one of the Spanish regions with a high prevalence of PD, comprehensive information regarding the functional characteristics of this population remains limited. This observational cross-sectional study aims to characterize the sociodemographic, clinical, cognitive, behavioral, and functional profile of individuals with Parkinson's disease in Galicia and to evaluate the validity and reliability of the Short Ph…","authors":"University of Vigo","venue":"NCT07780461","status":"recruiting","topics":["record"]},{"id":"trial-nct03161067","kind":"trial","title":"Investigation on the Bidirectional Cortical Neuroprosthetic System","date":"2026-08-21","observedAt":"2026-08-24","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT03161067","summary":"The Bidirectional Cortical Neuroprosthetic System (BiCNS) consists of NeuroPort Microelectrode Array Systems and NeuroPort Electrodes (Sputtered Iridium Oxide Film), Patient Pedestals, the NeuroPort BioPotential Signal Processing System, and the CereStim C96 Programmable Stimulator. The goals of this early feasibility study consist of safety and efficacy evaluations of this device.","authors":"Johns Hopkins University","venue":"NCT03161067 · NA","status":"recruiting","topics":["record"]},{"id":"trial-nct07778589","kind":"trial","title":"Comparison Between Radiofrequency,Hydrodissection and Cryoneurolysis in Chronic Ankle Pain","date":"2026-08-21","observedAt":"2026-08-24","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07778589","summary":"Ligamentous injuries of the ankle are common among athletes. Inversion injuries of the ankle account for 40% of all athletic injuries. The anterior talofibular ligament (ATFL) and the calcaneofibular ligament (CFL) are sequentially the most commonly injured ligaments when a plantar-flexed foot is forcefully inverted. The posterior talofibular ligament (PTFL) is rarely injured, except in association with a complete dislocation of the talus. Eighty percent of patients with lateral ankle injuries make a full recovery following conservative rehabilitation. Up to 20% of patients with an acute inversion injury develop…","authors":"Assiut University","venue":"NCT07778589 · NA","status":"not yet recruiting","topics":["record","stimulate","restore"]},{"id":"trial-nct06561828","kind":"trial","title":"Developing Transcranial Neuromodulation Protocols for Learning and Decision-Making","date":"2026-08-21","observedAt":"2026-08-24","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT06561828","summary":"Background: People with substance use disorder (SUD) often have changes in brain function that can make it difficult to control drug-seeking behavior. These changes may heighten the urge to use drugs or lessen the desire to seek nondrug-related rewards. Researchers want to know how a technique called transcranial magnetic stimulation (TMS) may cause changes in brain activity that may help people with SUD. Objective: To test TMS in healthy volunteers. Eligibility: Healthy people aged 18 to 45 years who are right-handed. Design: Participants can volunteer for up to 5 different experiments. Each experiment requires…","authors":"National Institute on Drug Abuse (NIDA)","venue":"NCT06561828 · EARLY_PHASE1","status":"recruiting","topics":["record","stimulate"]},{"id":"trial-nct05236010","kind":"trial","title":"Control Network Neuromodulation to Enhance Cognitive Training in Complex Traumatic Brain Injury","date":"2026-08-21","observedAt":"2026-08-24","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT05236010","summary":"The CONNECT-TBI Trial aims to develop safe, effective treatments for complex mTBI that improve cognitive functioning. Based on the compelling preliminary data generated by our study team, the objective of this study is to conduct a randomized, double-blinded, sham-controlled Phase II clinical trial of APT-3 combined with rTMS, HD-tDCS, or sham to treat cognitive control deficits in Veterans with complex mTBI and PPCS. At the Baseline Visit, participants will undergo demographic, neuropsychological, behavioral, and quality of life testing. They will also undergo structural MRI to permit modeling of their brain, r…","authors":"University of New Mexico","venue":"NCT05236010 · NA","status":"recruiting","topics":["record","stimulate","restore"]},{"id":"trial-nct07777991","kind":"trial","title":"Stimulation Evaluation for Neuromodulation Sensory Effects","date":"2026-08-21","observedAt":"2026-08-24","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07777991","summary":"The goal of this clinical trial is to learn how healthy adults experience low-level electrical stimulation delivered through the study device. This study is not intended to treat a medical condition. The main questions it aims to answer are: Is the study stimulation comfortable and well tolerated? What sensations do participants notice during stimulation? Can participants tell the difference between active stimulation and sham stimulation? Researchers will compare active stimulation with sham stimulation. Sham stimulation uses the same study procedures but does not deliver the study stimulation. This comparison…","authors":"Adraxe Corp.","venue":"NCT07777991 · NA","status":"not yet recruiting","topics":["stimulate"]},{"id":"trial-nct07587294","kind":"trial","title":"Efficacy and Safety of Ultrasound Modulation of Stellate Ganglion for the Prevention of Ventricular Arrhythmia in Patients With ST-segment Elevation Myocardial Infarction","date":"2026-08-21","observedAt":"2026-08-24","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07587294","summary":"The goal of this multicenter, double-blind, randomized controlled trial is to evaluate the efficacy and safety of low-intensity focused ultrasound (LIFU) stellate ganglion modulation for preventing ventricular arrhythmias after ST-segment elevation myocardial infarction (STEMI) in patients undergoing percutaneous coronary intervention (PCI). The main questions it aims to answer are: 1. Does LIFU reduce the frequency and duration of ventricular arrhythmias within 72 hours post-PCI compared to sham ultrasound? 2. Does LIFU improve electrophysiological stability, myocardial injury markers, cardiac function and hear…","authors":"Renmin Hospital of Wuhan University","venue":"NCT07587294 · NA","status":"recruiting","topics":["stimulate"]},{"id":"trial-nct04947462","kind":"trial","title":"Proprioceptive Sensorimotor Integration With Neural Interfaces for Hand Prostheses","date":"2026-08-21","observedAt":"2026-08-24","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT04947462","summary":"The purpose of this study is to characterize proprioceptive sensations in the missing limb of upper limb amputees using nerve stimulation, and to develop advanced controllers for moving a prosthesis. Proprioceptive sensations are the sensations that tell individuals where their hand is in space, and if it is moving. The research team uses Functional Electrical Stimulation (FES), which involves applying small electric currents to the nerves. These signals are then transferred to the brain just like the information about the individual's intact hand used to be transferred to their brain. This study will test diffe…","authors":"VA Office of Research and Development","venue":"NCT04947462 · NA","status":"recruiting","topics":["stimulate"]},{"id":"trial-nct04350359","kind":"trial","title":"Transcutaneous Tibial Nerve Stimulation for Spinal Cord Injury Neurogenic Bladder","date":"2026-08-21","observedAt":"2026-08-24","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT04350359","summary":"The purpose of this study is to determine if electric stimulation to the leg, called transcutaneous tibial nerve stimulation (TTNS), can improve bladder outcomes in acute spinal cord injury.","authors":"The University of Texas Health Science Center, Houston","venue":"NCT04350359 · NA","status":"completed","topics":["stimulate","restore"]},{"id":"trial-nct07779330","kind":"trial","title":"Maintenance Individualized Neuromodulation and Depression-detection Via Sensors for Early Treatment","date":"2026-08-21","observedAt":"2026-08-24","source":"ClinicalTrials.gov","sourceId":"clinicaltrials","sourceUrl":"https://clinicaltrials.gov/study/NCT07779330","summary":"This proposal seeks to carry out a prospective, single-arm open label study aimed at sustaining treatment-resistant depression (TRD) response in patients with TRD who had responded to prior individualized resting-state functional connectivity (rs-FC)-guided intermittent theta burst stimulation (iTBS). It also seeks to detect and predict relapse risk by integrating rs-FC iTBS with a TMS-adapted needs-based symptom-titrated algorithm based longitudinal ECT (STABLE) maintenance scheduling algorithm, and passive digital biomarkers.","authors":"National University Hospital, Singapore","venue":"NCT07779330 · NA","status":"not yet recruiting","topics":["stimulate"]},{"id":"paper-10.1021/jacs.6c15989","kind":"paper","title":"Photouncaging of an Opioid Peptide in Vivo Using Blue Light.","date":"2026-08-20","observedAt":"2026-08-24","source":"Europe PMC","sourceId":"europe-pmc","sourceUrl":"https://doi.org/10.1021/jacs.6c15989","summary":"Here we report blue light-driven in vivo photoactivation of TCA-DCCM-DAMGO, a caged derivative of the μ-opioid receptor (MOR) agonist DAMGO. TCA-DCCM-DAMGO is chemically stable in the dark, is inactive prior to illumination, and cleanly liberates DAMGO upon irradiation with blue light. Brain slice electrophysiology demonstrates rapid, light-triggered MOR activation. Following intracerebroventricular infusion of TCA-DCCM-DAMGO in the mouse brain, photoactivation in the ventral tegmental area with blue light elicited a rapid, opioid-dependent increase in locomotion. These results demonstrate the feasibility of in…","authors":"Li H, Song WS, Li A, Nawsheen S, Liao J, Martin A, Banghart MR.","venue":"Journal of the American Chemical Society","status":"Peer-reviewed / indexed","topics":["record"]},{"id":"preprint-10.64898/2026.08.16.745081","kind":"preprint","title":"From Scalp to Source: Precise Phase Retrieval of Intracerebral Epileptic Sources Based on Surface EEG","date":"2026-08-20","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.08.16.745081","summary":"Accurate phase tracking of deep-brain activity is critical for effective closed-loop and phase-locked neuromodulation therapies. However, direct access to deep neural phase through intracranial recordings remains clinically restrictive due to the invasiveness. Here we validate and clinically benchmark the Gabor-Nelson (GN) dipole estimation method for reconstructing deep-brain oscillatory phase from non-invasive scalp EEG. GN is a geometry-based, imaging-independent approach that offers computationally efficient dipole reconstruction and has rarely been applied to source-level phase estimation in human neuroscie…","authors":"Furuglyas K, Huszar-Kis M, Horvath B, Pejin A, Forgo N, Lango I, Singla S, Gorog M, Vass P, Chadaide Z, Laszlovszky T, Devinsky O, Bagic AI, Somogyvari Z, Berenyi A.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","stimulate"]},{"id":"preprint-10.21203/rs.3.rs-9966857/v1","kind":"preprint","title":"Brain–computer interface-assisted pneumatic hand training improves upper limb function after stroke: a randomized controlled trial and EEG characterization","date":"2026-08-20","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.21203/rs.3.rs-9966857/v1","summary":"Abstract Background The clinical efficacy of brain–computer interface (BCI)–based rehabilitation after stroke remains uncertain, particularly in the subacute phase, where evidence is limited and clinically meaningful improvement is seldom evaluated. This study aimed to investigate the therapeutic efficacy and electrophysiological mechanisms of BCI-assisted pneumatic hand training in subacute stroke. Methods In this prospective randomized controlled trial, 129 patients with stroke were assigned to a BCI group ( n = 72) or a control group ( n = 57). Upper limb function was assessed using FMA-UE, ARAT, WMFT, and MB…","authors":"Cheng X, Deng XY, Zheng MC, Guo Y, Ni X, Qiu R, Dou WB, Pan Y.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","restore"]},{"id":"preprint-10.21203/rs.3.rs-10203407/v1","kind":"preprint","title":"Transcranial magnetic stimulation-based brain-computer interface with neurofeedback facilitates motor imagery of different daily life hand actions","date":"2026-08-20","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.21203/rs.3.rs-10203407/v1","summary":"Abstract Background: Non-invasive brain-computer interfaces (BCIs) in combination with motor imagery (MI) and neurofeedback (NF) enable users to modulate motor-related brain activity without producing actual motor output. While most non-invasive MI-based BCIs decode only gross movements, daily tasks require finer finger and hand control. We developed a novel transcranial magnetic stimulation (TMS)-based BCI training using MI and NF to reinforce representations of complex hand actions in the brain. This proof-of-concept study examines the feasibility of using this BCI for hand function training. Methods: Twelve h…","authors":"Cheng H, Hochstrasser O, Tai E, Chong D, Voster N, Wunderlin C, Odermatt IA, Wenderoth N.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate","restore","personal"]},{"id":"preprint-10.64898/2026.08.19.745677","kind":"preprint","title":"Within-Subject Optogenetic Model Reveals Spatiotemporal Cortical Reorganization in Artificial Vision","date":"2026-08-19","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.08.19.745677","summary":"Visual prostheses can elicit simple percepts such as letter forms through dynamically patterned stimulation, yet naturalistic dynamic vision remains out of reach despite hardware fully capable of high-resolution temporal control. This persistent gap suggests the bottleneck lies in how artificial input is represented by the cortex itself. A fundamental question remains unresolved: when artificial vision bypasses natural retinal encoding, what is lost in cortical representation? We address this question in this paper using a retinal optogenetic mouse model that isolates the consequence of bypassing retinal encodin…","authors":"Gao X, Ren W, Zhang B, Zhou Y, Hu G, Xu Y, Chai C, Wang C, Zou Y, Wang L, Chen Y, Yang J, Sawan M.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"preprint-10.64898/2026.08.13.744740","kind":"preprint","title":"Astrocyte-Selective Wireless Deep Brain Stimulation by Magnetite Nanodiscs at Low Alternating Magnetic Field","date":"2026-08-19","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.08.13.744740","summary":"Astrocytes are essential regulators of synaptic transmission, brain homeostasis and behavior, and direct astrocyte activation has emerged as a promising therapeutic modality for a broad range of CNS disorders. However, selective activation of astrocytes in vivo currently requires viral transgene delivery, tethered fiber implants, or MRI-scale magnetic fields, limiting deployment across laboratories and translational settings. Here we introduce anti-GLAST-conjugated magnetite vortex nanodiscs (αGLAST-MND) that, together with a low-amplitude alternating magnetic field, enable wireless, transgene-free, cell-type-sp…","authors":"Cai Y, Wang J, CHIANG P.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","stimulate"]},{"id":"preprint-10.21203/rs.3.rs-10503490/v1","kind":"preprint","title":"Rapid cognitive-emotional responses to ultrasonic neuromodulation of anterior cingulate cortex in pain and depression","date":"2026-08-19","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.21203/rs.3.rs-10503490/v1","summary":"Abstract The anterior cingulate cortex (ACC) is a key brain center involved in cognitive and emotional processing that is implicated in a variety of neuropsychiatric disorders including chronic pain and depression. Circuit-targeted diagnosis and treatment of these disorders will require the capacity to precisely modulate ACC subregions. Toward that end, we recently developed and validated a novel low-intensity transcranial focused ultrasound device that can noninvasively and directly modulate ACC subdivisions in humans with millimeter precision. Here we describe the subjective reports of 36 individuals diagnosed…","authors":"Cooper B, Koppelmans V, Riis T, Feldman D, Kwon S, Brashear P, Guynn M, Okifuji A, Kubanek J, Mickey B.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["stimulate"]},{"id":"preprint-10.21203/rs.3.rs-10425839/v1","kind":"preprint","title":"Fast probabilistic spike deconvolution using optimized Markov chain Monte Carlo","date":"2026-08-19","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.21203/rs.3.rs-10425839/v1","summary":"Abstract Two-photon calcium imaging allows monitoring of large populations of neurons, but individual action potentials are often obscured under typical recording conditions. Algorithms for spike deconvolution estimate the underlying spike train of a neuron given an observed calcium trace. One powerful approach, Markov chain Monte Carlo (MCMC) spike inference, models the underlying calcium dynamics, iteratively adding, removing, and shifting spikes in an inferred spike train in continuous time to sample from the posterior probability of the spike train given the observed calcium signal. However, MCMC is computat…","authors":"Martins D, Goard M.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record"]},{"id":"preprint-10.64898/2026.08.12.744037","kind":"preprint","title":"Neurobehavioral effects of focused ultrasound-mediated blood-brain barrier opening","date":"2026-08-18","observedAt":"2026-08-24","source":"Preprint","sourceId":"preprints","sourceUrl":"https://doi.org/10.64898/2026.08.12.744037","summary":"Microbubble-enhanced focused ultrasound (MB-FUS) enables noninvasive blood-brain barrier (BBB) opening to improve the delivery of drugs and other therapeutics to the brain, supporting more effective treatment of brain disorders. The benefits of this rapidly advancing and highly versatile technology have been demonstrated in clinical trials, sparking a growing interest in expanding FUS applications that require higher intensity treatments, larger targeted brain volumes and larger therapeutics. However, in-depth safety profiling of such treatments has not been done and is limited in the clinic. Preclinical studies…","authors":"Elvig SK, Seas AA, Anastasiadis P, Wolff SBE.","venue":"Preprint","status":"Preprint · not peer reviewed","topics":["record","stimulate"]},{"id":"news-nibib-0-nih-demystifies-vital-biomedical-tech-congressional-staff","kind":"news","title":"NIH Demystifies Vital Biomedical Tech for Congressional Staff","date":"2025-08-15","observedAt":"2026-08-24","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/nih-demystifies-vital-biomedical-tech-congressional-staff","summary":"Biomedical engineers and imaging researchers gave 45 congressional staff a glimpse of transformative medical technologies on the horizon, underscoring the crucial role of medical tools in human health. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-1-innovative-imaging-tool-could-improve-diagnosis-treatment-hearing-loss","kind":"news","title":"Innovative imaging tool could improve diagnosis and treatment of hearing loss","date":"2025-08-04","observedAt":"2026-08-24","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/innovative-imaging-tool-could-improve-diagnosis-treatment-hearing-loss","summary":"Researchers from the Keck School of Medicine of USC with NIH funding including NIBIB have adapted a low-cost imaging method developed for ophthalmology and used it to visualize tiny structures in the human inner ear. &nbsp; Source: USC Keck School of Medicine News. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-2-scientists-develop-high-performance-mri-scanner-effort-define-microscopic-brain-structures","kind":"news","title":"Scientists Develop High-Performance MRI Scanner in Effort to Define Microscopic Brain Structures","date":"2025-07-16","observedAt":"2026-08-24","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/scientists-develop-high-performance-mri-scanner-effort-define-microscopic-brain-structures","summary":"A scientific team supported in part by NIH has developed a new, ultra-high-resolution brain imaging system that can reconstruct microscopic brain structures that are disrupted in neurological and neuropsychiatric brain disorders. The new system is a significant advance over conventional magnetic resonance imaging (MRI) scanners that cannot visualize these tiny but clinically important structures. Source: NIH More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["record"]},{"id":"news-nibib-3-high-tech-sticker-can-identify-real-human-emotions","kind":"news","title":"High-tech sticker can identify real human emotions","date":"2025-04-22","observedAt":"2026-08-24","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/high-tech-sticker-can-identify-real-human-emotions","summary":"Saying one thing while feeling another is part of being human, but bottling up emotions can have serious psychological consequences like anxiety or panic attacks. To help health care providers tell the difference, a team led by scientists at Penn State has created a stretchable, rechargeable sticker that can detect real emotions — by measuring things like skin temperature and heart rate — even when users put on a brave face. &nbsp;The researchers recently unveiled the wearable patch that can simultaneously and accurately track multiple emotional signals in a study published in the journal Nano Letters. Read more…","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["personal"]},{"id":"news-nibib-4-your-skin-breathing-new-wearable-device-can-measure-it","kind":"news","title":"Your skin is breathing. This new wearable device can measure it.","date":"2025-04-10","observedAt":"2026-08-24","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/your-skin-breathing-new-wearable-device-can-measure-it","summary":"Northwestern University researchers have developed the first wearable device for measuring gases emitted from and absorbed by the skin. By analyzing these gases, the device offers an entirely new way to assess skin health, including monitoring wounds, detecting skin infections, tracking hydration levels, quantifying exposure to harmful environmental chemicals and more. Source: Northwestern Now More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["personal"]},{"id":"news-nibib-5-ai-tool-can-track-effectiveness-multiple-sclerosis-treatments","kind":"news","title":"AI tool can track effectiveness of multiple sclerosis treatments","date":"2025-04-08","observedAt":"2026-08-24","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/ai-tool-can-track-effectiveness-multiple-sclerosis-treatments","summary":"A new artificial intelligence (AI) tool that can help interpret and assess how well treatments are working for patients with multiple sclerosis (MS) has been developed by University College London researchers. Source: University College London News More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["compute"]},{"id":"news-nibib-6-revealing-capillaries-cells-living-organs-ultrasound","kind":"news","title":"Revealing capillaries and cells in living organs with ultrasound","date":"2025-04-04","observedAt":"2026-08-24","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/revealing-capillaries-cells-living-organs-ultrasound","summary":"While medical centers use ultrasound daily, so far this technology has not been capable of observing body tissues at the scale of cells. Physicists at several universities including CalTech have now developed a microscopy technique based on ultrasound to reveal capillaries and cells across living organs -- something that wasn't possible before. Source: Delft University of Technology More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["stimulate"]},{"id":"news-nibib-7-decreasing-invasiveness-deep-brain-stimulation","kind":"news","title":"Decreasing the invasiveness of deep brain stimulation","date":"2025-03-20","observedAt":"2026-08-24","source":"NIH NIBIB News","sourceId":"nibib","sourceUrl":"https://www.nibib.nih.gov/news-events/newsroom/decreasing-invasiveness-deep-brain-stimulation","summary":"Researchers are developing a preclinical method to stimulate the brain without drilling into the skull by guiding a catheter through the cerebrospinal fluid. More","authors":"National Institute of Biomedical Imaging and Bioengineering","venue":"Official institutional news feed","status":"Official institutional news","topics":["stimulate"]}]};
